test("accepts saved Markdown text documents for local and virtual URIs", () => {
  for (const uriPath of ["/workspace/README.md", "/docs/guide.markdown", "/virtual/notes.md"]) {
    assert.equal(isEligibleMarkdown({ languageId: "markdown", isUntitled: false, tabKind: "text", uriPath }), true);
  }
})

test("rejects untitled, non-Markdown, diff, notebook, and custom inputs", () => {
  const base = { languageId: "markdown", isUntitled: false, tabKind: "text" as const, uriPath: "/docs/guide.md" };
  assert.equal(isEligibleMarkdown({ ...base, isUntitled: true }), false);
  assert.equal(isEligibleMarkdown({ ...base, languageId: "mdx" }), false);
  assert.equal(isEligibleMarkdown({ ...base, tabKind: "diff" }), false);
  assert.equal(isEligibleMarkdown({ ...base, tabKind: "notebook" }), false);
  assert.equal(isEligibleMarkdown({ ...base, tabKind: "custom" }), false);
})

test("rejects recognized agent Markdown names without excluding normal docs", () => {
  for (const path of [
    "/repo/AGENTS.md",
    "/repo/SKILL.md",
    "/repo/review.prompt.md",
    "/repo/team.instructions.md",
    "/repo/builder.chatagent.md",
    "/repo/audit.agent.md",
    "/repo/encoded%2Eprompt%2Emd",
  ]) {
    assert.equal(isAgentMarkdownPath(path), true, path);
  }
  for (const path of ["/repo/README.md", "/repo/agent-guide.md", "/repo/skills.md"]) {
    assert.equal(isAgentMarkdownPath(path), false, path);
  }
})

test("uses the highest-precedence existing setting override", () => {
  const context = { hasWorkspace: true, hasWorkspaceFolder: true, isMultiRoot: true };
  assert.deepEqual(resolveSettingTarget({ globalValue: true }, context), {
    target: "global",
    overrideInLanguage: false,
  });
  assert.deepEqual(resolveSettingTarget({ globalLanguageValue: true, workspaceFolderValue: false }, context), {
    target: "global",
    overrideInLanguage: true,
  });
  assert.deepEqual(resolveSettingTarget({ workspaceLanguageValue: false, globalLanguageValue: true }, context), {
    target: "workspace",
    overrideInLanguage: true,
  });
  assert.deepEqual(resolveSettingTarget({ workspaceFolderLanguageValue: true, workspaceLanguageValue: false }, context), {
    target: "workspaceFolder",
    overrideInLanguage: true,
  });
})

test("chooses folder, workspace, or global for a new override", () => {
  assert.deepEqual(resolveSettingTarget(undefined, {
    hasWorkspace: true,
    hasWorkspaceFolder: true,
    isMultiRoot: true,
  }), { target: "workspaceFolder", overrideInLanguage: false });
  assert.deepEqual(resolveSettingTarget(undefined, {
    hasWorkspace: true,
    hasWorkspaceFolder: true,
    isMultiRoot: false,
  }), { target: "workspace", overrideInLanguage: false });
  assert.deepEqual(resolveSettingTarget(undefined, {
    hasWorkspace: false,
    hasWorkspaceFolder: false,
    isMultiRoot: false,
  }), { target: "global", overrideInLanguage: false });
})

test("reports no progress for a short document", () => {
  assert.deepEqual(getReadingState(0, 600, 700), {
    progress: 0,
    scrollable: false,
    showBackToTop: false,
  });
})

test("clamps progress and shows back to top after the midpoint", () => {
  assert.deepEqual(getReadingState(-20, 2_000, 800), {
    progress: 0,
    scrollable: true,
    showBackToTop: false,
  });
  const middle = getReadingState(700, 2_000, 800);
  assert.equal(middle.progress, 700 / 1_200);
  assert.equal(middle.showBackToTop, true);
  assert.equal(getReadingState(3_000, 2_000, 800).progress, 1);
})

test("keeps back to top hidden on a small scroll range", () => {
  const state = getReadingState(400, 1_000, 500);
  assert.equal(state.scrollable, true);
  assert.equal(state.showBackToTop, false);
})

test("tracks current requests and invalidates stale generations", () => {
  const session = new PreviewSessionState();
  const first = session.nextGeneration();
  assert.equal(session.isCurrent(first), true);
  const second = session.nextGeneration();
  assert.equal(session.isCurrent(first), false);
  assert.equal(session.isCurrent(second), true);
})

test("suppresses and restores one URI without affecting another", () => {
  const session = new PreviewSessionState();
  session.suppress("file:///one.md");
  assert.equal(session.isSuppressed("file:///one.md"), true);
  assert.equal(session.isSuppressed("file:///two.md"), false);
  session.clearSuppression("file:///one.md");
  assert.equal(session.isSuppressed("file:///one.md"), false);
})

test("allows one warning in a window session", () => {
  const session = new PreviewSessionState();
  assert.equal(session.claimWarning(), true);
  assert.equal(session.claimWarning(), false);
})

test("installs one idempotent set of reading controls", async () => {
  const happyWindow = new HappyWindow({ url: "https://preview.invalid/" });
  const previewWindow = happyWindow as unknown as Window;
  happyWindow.document.body.innerHTML = `
    <h1>Guide</h1>
    <pre><code class="language-ts">const value = 1;\n</code></pre>
    <pre class="mermaid"><code class="language-mermaid">graph TD</code></pre>
    <pre><code class="language-math">x^2</code></pre>
    <table><tbody><tr><td>Cell</td></tr></tbody></table>
  `;
  let copied = "";
  Object.defineProperty(happyWindow.navigator, "clipboard", {
    configurable: true,
    value: { writeText: async (text: string) => { copied = text; } },
  });
  Object.defineProperty(happyWindow, "innerHeight", { configurable: true, value: 800 });
  Object.defineProperty(happyWindow, "scrollY", { configurable: true, value: 700 });
  Object.defineProperty(happyWindow.document.documentElement, "scrollHeight", {
    configurable: true,
    value: 2_000,
  });

  const runtime = installPreviewEnhancements(previewWindow);
  runtime.refresh();
  runtime.refresh();
  await happyWindow.happyDOM.whenAsyncComplete();

  assert.equal(happyWindow.document.querySelectorAll(".open-md-preview__progress").length, 1);
  assert.equal(happyWindow.document.querySelectorAll(".open-md-preview__back-to-top").length, 1);
  assert.equal(happyWindow.document.querySelectorAll(".open-md-preview__copy").length, 1);
  assert.equal(happyWindow.document.querySelectorAll(".open-md-preview__table-wrap").length, 1);

  const progress = happyWindow.document.querySelector(".open-md-preview__progress") as unknown as HTMLElement | null;
  const backToTop = happyWindow.document.querySelector(".open-md-preview__back-to-top") as unknown as HTMLButtonElement | null;
  assert.equal(progress?.hidden, false);
  assert.equal(progress?.getAttribute("aria-valuenow"), "58");
  assert.equal(backToTop?.hidden, false);

  const copy = happyWindow.document.querySelector(".open-md-preview__copy") as unknown as HTMLButtonElement | null;
  copy?.click();
  await Promise.resolve();
  await Promise.resolve();
  assert.equal(copied, "const value = 1;\n");
  assert.equal(copy?.textContent, "Copied");

  runtime.dispose();
  assert.equal(happyWindow.document.querySelectorAll("[data-open-md-preview-control]").length, 0);
  assert.equal(happyWindow.document.querySelectorAll("table").length, 1);
  await happyWindow.close();
})

